/**
 * The look of the view, for any world — CODE-SPLIT.
 *
 * A world may ask how its view is drawn (client-hints profile, `hints:view`):
 * a fixed exposure or an eye that adapts, bloom around what is brightest, the
 * sun's flare, and a colour grade. This module draws them for a world that
 * has no planet, with the passes a planet's view already uses, each in a
 * chunk of its own fetched once the world asks for it. It is itself loaded
 * only by dynamic `import()` from the session, for a world that sets one of
 * the hints: a world that asks for no look is drawn as it always was, and
 * fetches nothing.
 *
 * While a planet draws the view this stands down: the planet reads the same
 * hints where its own are left at `auto` (`lookHint`), and two sets of passes
 * on one camera would draw the look twice.
 *
 * What differs from a planet's: nothing is on unless asked (a planet's `auto`
 * adapts, blooms and flares; an ordinary world's `auto` draws none of them);
 * the sun is the world's first directional light; and the bloom draws the
 * scene in high dynamic range, so a sky brighter than white glows as bright
 * as it is.
 */
// Types only: an engine class imported here by value is one more module the
// bundler may move into first paint, so the ray toward the sun is the effects
// chunk's to cast, and directions are handed on as the engine made them.
import type { Vector3 } from '@babylonjs/core/Maths/math.vector';
import type { FreeCamera } from '@babylonjs/core/Cameras/freeCamera';
import type { Scene } from '@babylonjs/core/scene';
import { exposureOf, type Exposure } from '../planet/eye';
import { gradeOf } from '../planet/gradeFocus';
import type { EyeHandle, EyeModule, GradeFocusHandle, GradeFocusModule, SunEffectsHandle } from '../planet/planetView';

type HintReader = (name: string) => string | null | undefined;
type Vec3 = [number, number, number];
interface Point {
  x: number;
  y: number;
  z: number;
}

/** The effects chunk as this module asks for it: `hdr` draws the scene in high dynamic range under the bloom. */
export interface ViewEffectsModule {
  createSunEffects(scene: Scene, camera: FreeCamera, opts: { engineKind?: string; bloom: boolean; hdr?: boolean }): SunEffectsHandle;
  /** Whether nothing stands between the eye and the sun, as far as `reach`: glass and a backdrop do not. */
  sunInSight?(scene: Scene, eye: Point, toward: Point, reach: number): boolean;
}

/** What the world asks of the view, after what the visitor's device affords. */
export interface ViewAsk {
  exposure: Exposure | null;
  /** 0 to 1; 0 for none. */
  bloom: number;
  flare: number;
  /** The colour table's address, or null. */
  grade: string | null;
}

const strength = (v: string | null | undefined): number => {
  if (v === undefined || v === null || v === 'auto' || v === 'none') return 0;
  const n = Number(v);
  return Number.isFinite(n) ? Math.min(1, Math.max(0, n)) : 0;
};

/**
 * What an ordinary world's `hints:view` asks for. `auto` asks for nothing:
 * the limits and the speed shape an adapting eye and do not turn one on.
 * Where the device does not afford it there is no exposure, grade or bloom;
 * the flare is cheap and stays.
 */
export function viewAsk(hint: HintReader, allowed: { exposure: boolean; bloom: boolean }, worldUrl: string): ViewAsk {
  const asked = hint('view.exposure');
  const exposure =
    allowed.exposure && asked && asked !== 'auto'
      ? exposureOf((name) => (name === 'planet.exposure' ? (asked === 'adapt' ? 'auto' : asked) : hint(`view.${name.slice(7)}`)), true)
      : null;
  return {
    exposure,
    bloom: allowed.bloom ? strength(hint('view.bloom')) : 0,
    flare: strength(hint('view.sun-flare')),
    grade: gradeOf(() => hint('view.grade'), allowed.exposure, worldUrl),
  };
}

export interface ViewLookOptions {
  scene: Scene;
  camera: FreeCamera;
  engineKind?: string;
  /** The world's hints, read each frame: a script may change them. */
  hint: HintReader;
  /** The world document's address: the grade's table is beside it. */
  worldUrl: string;
  /** What the visitor's device affords, as the planet's view reads it. */
  quality?: () => { eyeAdaptation?: boolean; sky?: { bloom?: boolean } } | undefined;
  /** True while something else draws the view's look: a planet holding the visitor. */
  standDown?: () => boolean;
  fetchImpl?: (url: string) => Promise<Response>;
  warn: (name: string, detail: string) => void;
  /** Where the eye is; by default the camera. */
  eye?: () => Point;
  /** Toward the world's sun and its colour, or null for a world with none; by default its first directional light. */
  sun?: () => { toward: Point; tint: Vec3 } | null;
  /** Whether nothing stands between the eye and the sun; by default a ray against what hides it. */
  clear?: (eye: Point, toward: Point) => boolean;
  loadEffects?: () => Promise<ViewEffectsModule>;
  loadEye?: () => Promise<EyeModule>;
  loadGradeFocus?: () => Promise<GradeFocusModule>;
}

export interface ViewLook {
  /** Each frame, before it is drawn. */
  tick(deltaMs: number): void;
  dispose(): void;
}

/** How many frames pass between looks for something in front of the sun. */
const SUN_SIGHT_EVERY = 6;
/** A direction for the passes that are handed one and, with no sun, do not read it. */
const NO_SUN: Point = { x: 0, y: 1, z: 0 };

export function createViewLook(o: ViewLookOptions): ViewLook {
  const { scene, camera } = o;
  const kind = o.engineKind ? { engineKind: o.engineKind } : {};
  const loadEffects = o.loadEffects ?? (() => import('../planet/sunEffectsChunk') as Promise<ViewEffectsModule>);
  const loadEye = o.loadEye ?? (() => import('../planet/eyeChunk'));
  const loadGradeFocus = o.loadGradeFocus ?? (() => import('../planet/gradeFocusChunk'));
  const fetchImpl = o.fetchImpl ?? ((url: string) => fetch(url));

  const eyeAt = o.eye ?? (() => camera.globalPosition);
  const sunOf =
    o.sun ??
    (() => {
      const light = scene.lights.find((l) => l.isEnabled() && l.getClassName() === 'DirectionalLight') as
        | {
            direction: Vector3;
            diffuse: { r: number; g: number; b: number };
            parent: unknown;
            computeWorldMatrix(force: boolean): unknown;
            computeTransformedInformation(): boolean;
            getShadowDirection(): Vector3;
          }
        | undefined;
      if (!light || light.direction.lengthSquared() === 0) return null;
      // A model's sun points down its own axis, on a node the model turned: where it shines is the light's
      // direction through the nodes above it, which the engine works out when asked.
      let shines = light.direction;
      if (light.parent) {
        light.computeWorldMatrix(true);
        light.computeTransformedInformation();
        shines = light.getShadowDirection();
      }
      if (shines.lengthSquared() === 0) return null;
      const toward = shines.scale(-1).normalize();
      const c = light.diffuse;
      const top = Math.max(1, c.r, c.g, c.b);
      return { toward, tint: [c.r / top, c.g / top, c.b / top] as Vec3 };
    });
  let sight: ViewEffectsModule['sunInSight'];
  const clearOf = o.clear ?? ((eye: Point, toward: Point) => sight?.(scene, eye, toward, camera.maxZ) ?? true);

  let gone = false;
  /** Raised each time what was made is given back, so a chunk that arrives late makes nothing. */
  let epoch = 0;
  let frame = 0;

  let effects: SunEffectsHandle | undefined;
  let effectsBloom = false;
  let effectsAsked = false;
  let effectsFailed = false;
  let sunClear = true;

  let eyeFx: EyeHandle | undefined;
  let eyeAsked = false;

  let gradeFx: GradeFocusHandle | undefined;
  let gradeAsked = false;

  const lower = (): void => {
    epoch += 1;
    effects?.dispose();
    eyeFx?.dispose();
    gradeFx?.dispose();
    effects = eyeFx = gradeFx = undefined;
    effectsAsked = eyeAsked = gradeAsked = effectsFailed = false;
  };

  const drawEffects = (ask: ViewAsk, bloomAllowed: boolean): void => {
    // A flare made without the bloom's pipeline cannot bloom: made again once the world asks for both.
    if (effects && ask.bloom > 0 && !effectsBloom) {
      effects.dispose();
      effects = undefined;
      effectsAsked = false;
    }
    if (!effects) {
      if (effectsAsked || (ask.bloom <= 0 && ask.flare <= 0)) return;
      effectsAsked = true;
      const withBloom = bloomAllowed && ask.bloom > 0;
      const mine = epoch;
      void (async () => {
        try {
          const m = await loadEffects();
          if (gone || mine !== epoch || effects) return;
          sight = m.sunInSight;
          effects = m.createSunEffects(scene, camera, { ...kind, bloom: withBloom, hdr: withBloom });
          effectsBloom = withBloom;
        } catch (err) {
          effectsFailed = true;
          o.warn('veml:client-hints:view-effects-unavailable', String(err));
        }
      })();
      return;
    }
    const eye = eyeAt();
    const sun = ask.flare > 0 ? sunOf() : null;
    if (sun && frame % SUN_SIGHT_EVERY === 0) sunClear = clearOf(eye, sun.toward);
    const flare = sun && sunClear ? ask.flare : 0;
    effects.update(eye as Vector3, (sun?.toward ?? NO_SUN) as Vector3, flare, ask.bloom, sun?.tint);
  };

  const drawEye = (ask: ViewAsk, deltaMs: number): void => {
    const e = ask.exposure;
    if (!eyeFx) {
      const wanted = e?.mode === 'auto' || (e?.mode === 'fixed' && e.value !== 1);
      // The exposure is drawn over the bloomed view, so the bloom's passes are on the camera first.
      const bloomComing = ask.bloom > 0 && !effects && !effectsFailed;
      if (eyeAsked || !wanted || bloomComing) return;
      eyeAsked = true;
      const mine = epoch;
      void (async () => {
        try {
          const m = await loadEye();
          if (!gone && mine === epoch && !eyeFx) eyeFx = m.createEye(scene, camera, { ...kind, sunbeams: false });
        } catch (err) {
          o.warn('veml:client-hints:view-exposure-unavailable', String(err));
        }
      })();
      return;
    }
    eyeFx.update({ dtS: deltaMs / 1000, exposure: e, sunbeams: 0, sunHeight: 0, sun: NO_SUN as Vector3 });
  };

  const drawGrade = (ask: ViewAsk): void => {
    if (!gradeFx) {
      if (gradeAsked || !ask.grade) return;
      gradeAsked = true;
      const mine = epoch;
      void (async () => {
        try {
          const m = await loadGradeFocus();
          if (!gone && mine === epoch && !gradeFx) gradeFx = m.createGradeFocus(scene, camera, { ...kind, fetchImpl, warn: o.warn });
        } catch (err) {
          o.warn('veml:client-hints:view-grade-unavailable', String(err));
        }
      })();
      return;
    }
    gradeFx.update({ grade: ask.grade, focus: null });
  };

  return {
    tick(deltaMs) {
      if (gone) return;
      if (o.standDown?.()) {
        if (effects || eyeFx || gradeFx || effectsAsked || eyeAsked || gradeAsked) lower();
        return;
      }
      const q = o.quality?.();
      const bloomAllowed = q?.sky?.bloom !== false;
      const ask = viewAsk(o.hint, { exposure: q?.eyeAdaptation !== false, bloom: bloomAllowed }, o.worldUrl);
      drawEffects(ask, bloomAllowed);
      drawEye(ask, deltaMs);
      drawGrade(ask);
      frame += 1;
    },
    dispose() {
      if (gone) return;
      lower();
      gone = true;
    },
  };
}
